/**
 * Packed Unicode emoji table for the web picker — id, glyph, search keywords,
 * and the five skin-tone variants for the emoji that have them.
 *
 * GENERATED DATA, derived from `@emoji-mart/data` v1.2.1 (`sets/15/native.json`,
 * MIT — https://github.com/missive/emoji-mart), which the desktop client already
 * depends on for the same purpose. The web client deliberately shares no code
 * with desktop, and cannot take a new npm dependency in this change, so the
 * table is vendored here instead of imported. If web ever gains
 * `@emoji-mart/data` as a dependency, delete this file and parse that JSON.
 *
 * Wire format, chosen so the whole table costs eight source lines rather than
 * 7480:
 *
 *   category  := record (";" record)*
 *   record    := id "|" glyph "|" keywords "|" toneGlyphs
 *
 * `keywords` is a space-separated blob (the id's own words are omitted — the id
 * is searched directly). `toneGlyphs` is the five tone variants separated by
 * commas — a comma never occurs inside an emoji sequence, and splitting on one
 * avoids needing grapheme segmentation to read the table back. It is empty for
 * an emoji with no tone variants. See ./unicodeEmoji.ts for the parser and the
 * reason the variants are stored rather than derived.
 */

export interface PackedEmojiCategory {
  readonly id: string;
  readonly label: string;
  /** Packed records — see the format note above. */
  readonly table: string;
}

